const ts = require\('typescript'\);
const cfg = ts.readConfigFile\('tsconfig.json', ts.sys.readFile\);
const parsed = ts.parseJsonConfigFileContent\(cfg.config, ts.sys, '.'\);
parsed.options.incremental = false;
const files = parsed.fileNames.filter\(f => f.includes\('ArchitectScene'\) || f.includes\('home-page'\)\);
const program = ts.createProgram\(files, parsed.options\);
const diags = ts.getPreEmitDiagnostics\(program\);
if \(diags.length\) {
  diags.forEach\(d => {
    const msg = ts.flattenDiagnosticMessageText\(d.messageText, '\\\\n'\);
    const file = d.file ? d.file.fileName + ':' + \(d.file.getLineAndCharacterOfPosition\(d.start\).line+1\) : '';
    console.log\(file, msg\);
  }\);
} else {
  console.log\('No type errors'\);
}
